      for(let i=0;i<4;i++){
        const nx=x+DIRS[i][1],ny=y+DIRS[i][2];if(!floor(nx,ny))continue;
        const z=key(nx,ny);if(seen[z])continue;
        seen[z]=1;first[z]=(p===sk?z:first[p]);
        if(nx===tx&&ny===ty){const f=first[z];return [f%W,(f/W)|0];}
        q[b++]=z;
      }
    }
    return [e.x,e.y];
  }

