      if(o.courier.battery<stepCost)return null;
      if(o.courier.battery===stepCost&&!o.chargers.some(c=>c.x===nx&&c.y===ny))return null;
    }
    let danger=0;
    for(const e of o.enemies){
      if(nx===e.x&&ny===e.y)return null;
      let ex=e.x,ey=e.y;
      const moves=e.kind==='hunter'?(o.tick%2===0):(o.tick%3===0);
      if(moves){
        if(e.kind==='hunter'){
          const z=hunterStep(e,nx,ny);ex=z[0];ey=z[1];
          if(ex===nx&&ey===ny)return null;
        } else {
          if(Math.abs(e.x-nx)+Math.abs(e.y-ny)===1)return null;
        }
      }
      const md=Math.abs(ex-nx)+Math.abs(ey-ny);
      if(e.kind==='hunter'){
        if(md===1)danger+=42;else if(md===2)danger+=18;else if(md===3)danger+=7;else if(md===4)danger+=2;
      }else{
        if(md===1)danger+=24;else if(md===2)danger+=9;else if(md===3)danger+=3;
      }
    }
    return danger;
  }

  function chooseMove(goal){
    const gd=goal?bfs(goal.x,goal.y):null;
    let best=null;
    for(let i=0;i<5;i++){
      const wait=i===4, nx=o.courier.x+(wait?0:DIRS[i][1]),ny=o.courier.y+(wait?0:DIRS[i][2]);
      const danger=assess(nx,ny,wait);if(danger===null)continue;
      let dist=goal?gd[key(nx,ny)]:0;if(dist<0)dist=999;
      let score=dist*5+danger+(wait?2.2:0);
      if(memory.last&&nx===memory.last[0]&&ny===memory.last[1])score+=1.6;
      if(!best||score<best.score)best={i,nx,ny,score};
    }
    if(!best)return {type:'wait'};
    memory.last=[o.courier.x,o.courier.y];
    return best.i===4?{type:'wait'}:{type:'move',dir:DIRS[best.i][0]};
  }

  let action;
  const hereTask=taskGoal&&o.courier.x===taskGoal.x&&o.courier.y===taskGoal.y;
  if(chargeMode&&hereTask&&o.courier.battery<chargeNeed){
    if(assess(o.courier.x,o.courier.y,true)!==null)action={type:'charge'};
    else action=chooseMove(taskGoal);
  } else if(!chargeMode&&task&&hereTask){
    if(assess(o.courier.x,o.courier.y,true)===null)action=chooseMove(taskGoal);
    else if(task.type==='pickup')action={type:'pickup',id:task.id};
    else action={type:'deliver'};
  } else if(taskGoal) action=chooseMove(taskGoal);
  else action=chooseMove(null);
  return {action,memory};
}

module.exports={act};
"}

