{"content":"'use strict';

function act(o, memory) {
  const W=o.width,H=o.height,M=o.map;
  const DIRS=[['N',0,-1],['E',1,0],['S',0,1],['W',-1,0]];
  const key=(x,y)=>y*W+x;
  const floor=(x,y)=>x>=0&&y>=0&&x<W&&y<H&&M[y][x]!== '#';

  function bfs(sx,sy) {
    const n=W*H, d=new Int16Array(n); d.fill(-1);
    const q=new Int16Array(n); let a=0,b=0;
    if (!floor(sx,sy)) return d;
    const sk=key(sx,sy); d[sk]=0; q[b++]=sk;
    while(a<b) {
      const p=q[a++], x=p%W, y=(p/W)|0, nd=d[p]+1;
      for(let i=0;i<4;i++) {
        const nx=x+DIRS[i][1],ny=y+DIRS[i][2];
        if(!floor(nx,ny)) continue;
        const z=key(nx,ny);
        if(d[z]<0){d[z]=nd;q[b++]=z;}
      }
    }
    return d;
  }

  if(!memory || memory.v!==3) {
    const pts=[];
    function addp(p){
      for(let i=0;i<pts.length;i++) if(pts[i][0]===p.x&&pts[i][1]===p.y) return i;
      pts.push([p.x,p.y]); return pts.length-1;
    }
    for(const c of o.chargers)addp(c);
    for(const j of o.jobs){addp(j.from);addp(j.to);}
    const dm=[];
    for(let i=0;i<pts.length;i++){
      const d=bfs(pts[i][0],pts[i][1]);
      for(let k=0;k<pts.length;k++)dm.push(d[key(pts[k][0],pts[k][1])]);
    }
    memory={v:3,pts,dm,target:null,planTick:-999,last:null,seen:{}};
  }

  for(const e of o.enemies) memory.seen[e.id]={x:e.x,y:e.y,t:o.tick,kind:e.kind};
  const P=memory.pts, PN=P.length;
  function pi(p){for(let i=0;i<PN;i++)if(P[i][0]===p.x&&P[i][1]===p.y)return i;return -1;}
  function pd(a,b){const z=memory.dm[a*PN+b];return z<0?999:z;}
  const curD=bfs(o.courier.x,o.courier.y);
  function cd(p){const z=curD[key(p.x,p.y)];return z<0?999:z;}
  function nearCharge(p){
    const a=pi(p); let best=999;
    for(const c of o.chargers){const z=a>=0?pd(a,pi(c)):999;if(z<best)best=z;}
    return best;
  }
  function nearestCharge(){
    let best=null,bd=999;
    for(const c of o.chargers){const d=cd(c);if(d<bd){bd=d;best=c;}}
    return {p:best,d:bd};
  }
  const byId={}; for(let i=0;i<o.jobs.length;i++)byId[o.jobs[i].id]=o.jobs[i];
  function cargoWeight(maskMode){
    let z=0;
    if(maskMode===undefined){for(const id of o.courier.cargo){const j=byId[id];if(j)z+=j.weight;}return z;}
    for(let i=0;i<o.jobs.length;i++)if(maskMode&(1<<i))z+=o.jobs[i].weight;
    return z;
  }

  function targetValid(t){
    if(!t)return false;
    if(t.type==='pickup'){const j=byId[t.id];return !!j&&j.status==='available';}
    if(t.type==='deliver'){const j=byId[t.id];return !!j&&j.status==='carried';}
    return false;
  }

  function makePlan(){
    const n=o.jobs.length;
    let av=0,car=0;
    for(let i=0;i<n;i++){
      if(o.jobs[i].status==='available')av|=1<<i;
      else if(o.jobs[i].status==='carried')car|=1<<i;
    }
    const startLoc=-1, startTime=o.tick;
    let calls=0;
    function travel(loc,p){return loc<0?cd(p):pd(loc,pi(p));}
    function better(a,b){
      if(!b)return true;
      if(a.val!==b.val)return a.val>b.val;
      if(a.count!==b.count)return a.count>b.count;
      return a.end<b.end;
    }
    function dfs(loc,time,A,C,first,depth){
      calls++;
      let aa=A,cc=C;
      for(let i=0;i<n;i++)if(o.jobs[i].deadline<time){aa&=~(1<<i);cc&=~(1<<i);}
      let best={val:0,count:0,end:time,first:first};
      const wt=cargoWeight(cc);
      for(let i=0;i<n;i++)if(aa&(1<<i)){
        const j=o.jobs[i]; if(wt+j.weight>o.cargoCapacity)continue;
        const d=travel(loc,j.from); if(d>=999)continue;
        const nt=time+d+1;
        if(nt>j.deadline)continue;
        const f=first||{type:'pickup',id:j.id,x:j.from.x,y:j.from.y};
        const r=dfs(pi(j.from),nt,aa&~(1<<i),cc|(1<<i),f,depth+1);
        if(better(r,best))best=r;
      }
      const used={};
      for(let i=0;i<n;i++)if(cc&(1<<i)){
        const j=o.jobs[i],k=j.to.x+','+j.to.y;if(used[k])continue;used[k]=1;
        const d=travel(loc,j.to);if(d>=999)continue;
        const at=time+d;
        let nc=cc,gain=0,cnt=0;
        for(let q=0;q<n;q++)if((cc&(1<<q))&&o.jobs[q].to.x===j.to.x&&o.jobs[q].to.y===j.to.y){
          nc&=~(1<<q);
          if(o.jobs[q].deadline>=at){gain+=o.jobs[q].value;cnt++;}
        }
        if(!cnt)continue;
        const f=first||{type:'deliver',id:j.id,x:j.to.x,y:j.to.y};
        const r=dfs(pi(j.to),at+1,aa,nc,f,depth+1);
        r.val+=gain;r.count+=cnt;
        if(better(r,best))best=r;
      }
      return best;
    }
    return dfs(startLoc,startTime,av,car,null,0).first;
  }

  if(!targetValid(memory.target)||o.tick-memory.planTick>=7){
    memory.target=makePlan(); memory.planTick=o.tick;
  }

  let task=memory.target;
  let taskGoal=task?{x:task.x,y:task.y}:null;
  const wt=cargoWeight(), stepCost=wt>3?2:1;
  let chargeMode=false,chargeNeed=0;
  if(taskGoal){
    const dg=cd(taskGoal);
    let reserve=4;
    if(task.type==='deliver') reserve=nearCharge(taskGoal)+4;
    else {
      const j=byId[task.id],nw=wt+(j?j.weight:0),nc=nw>3?2:1;
      let after=nearCharge(taskGoal)*nc;
      if(j){
        const direct=pd(pi(j.from),pi(j.to))*nc+nearCharge(j.to)+3;
        if(direct<after)after=direct;
      }
      reserve=after+3;
    }
    const required=dg*stepCost+reserve;
    const nc=nearestCharge();
    const urgent=task.type==='deliver'&&byId[task.id]&&byId[task.id].deadline-o.tick<=dg+5;
    if(o.courier.battery<=dg*stepCost+1 || (!urgent&&o.courier.battery<Math.min(76,required))){
      if(nc.p && !(nc.d===0&&o.courier.battery>=Math.min(90,Math.max(55,required)))){
        chargeMode=true;taskGoal={x:nc.p.x,y:nc.p.y};chargeNeed=Math.min(90,Math.max(55,required));
      }
    }
    if(nc.d===0&&!urgent&&o.courier.battery<70){
      chargeMode=true;taskGoal={x:nc.p.x,y:nc.p.y};chargeNeed=Math.min(90,Math.max(72,required));
    }
  } else {
    const nc=nearestCharge();
    if(nc.p&&o.courier.battery<75){chargeMode=true;taskGoal={x:nc.p.x,y:nc.p.y};chargeNeed=90;}
  }

  function hunterStep(e,tx,ty){
    if(e.x===tx&&e.y===ty)return [e.x,e.y];
    const n=W*H,q=new Int16Array(n),seen=new Uint8Array(n),first=new Int16Array(n);
    let a=0,b=0,sk=key(e.x,e.y);q[b++]=sk;seen[sk]=1;first[sk]=-1;
    while(a<b){
      const p=q[a++],x=p%W,y=(p/W)|0;
      for(let i=0;i<4;i++){
        const nx=x+DIRS[i][1],ny=y+DIRS[i][2];if(!floor(nx,ny))continue;
        const z=key(nx,ny);if(seen[z])continue;
        seen[z]=1;first[z]=(p===sk?z:first[p]);
        if(nx===tx&&ny===ty){const f=first[z];return [f%W,(f/W)|0];}
        q[b++]=z;
      }
    }
    return [e.x,e.y];
  }

  function assess(nx,ny,isWait){
    if(!floor(nx,ny))return null;
    if(!isWait){
      if(o.courier.battery<stepCost)return null;
      if(o.courier.battery===stepCost&&!o.chargers.some(c=>c.x===nx&&c.y===ny))return null;
    }
    let danger=0;
    for(const e of o.enemies){
      if(nx===e.x&&ny===e.y)return null;
      let ex=e.x,ey=e.y;
      const moves=e.kind==='hunter'?(o.tick%2===0):(o.tick%3===0);
      if(moves){
        if(e.kind==='hunter'){
          const z=hunterStep(e,nx,ny);ex=z[0];ey=z[1];
          if(ex===nx&&ey===ny)return null;
        } else {
          if(Math.abs(e.x-nx)+Math.abs(e.y-ny)===1)return null;
        }
      }
      const md=Math.abs(ex-nx)+Math.abs(ey-ny);
      if(e.kind==='hunter'){
        if(md===1)danger+=42;else if(md===2)danger+=18;else if(md===3)danger+=7;else if(md===4)danger+=2;
      }else{
        if(md===1)danger+=24;else if(md===2)danger+=9;else if(md===3)danger+=3;
      }
    }
    return danger;
  }

  function chooseMove(goal){
    const gd=goal?bfs(goal.x,goal.y):null;
    let best=null;
    for(let i=0;i<5;i++){
      const wait=i===4, nx=o.courier.x+(wait?0:DIRS[i][1]),ny=o.courier.y+(wait?0:DIRS[i][2]);
      const danger=assess(nx,ny,wait);if(danger===null)continue;
      let dist=goal?gd[key(nx,ny)]:0;if(dist<0)dist=999;
      let score=dist*5+danger+(wait?2.2:0);
      if(memory.last&&nx===memory.last[0]&&ny===memory.last[1])score+=1.6;
      if(!best||score<best.score)best={i,nx,ny,score};
    }
    if(!best)return {type:'wait'};
    memory.last=[o.courier.x,o.courier.y];
    return best.i===4?{type:'wait'}:{type:'move',dir:DIRS[best.i][0]};
  }

  let action;
  const hereTask=taskGoal&&o.courier.x===taskGoal.x&&o.courier.y===taskGoal.y;
  if(chargeMode&&hereTask&&o.courier.battery<chargeNeed){
    if(assess(o.courier.x,o.courier.y,true)!==null)action={type:'charge'};
    else action=chooseMove(taskGoal);
  } else if(!chargeMode&&task&&hereTask){
    if(assess(o.courier.x,o.courier.y,true)===null)action=chooseMove(taskGoal);
    else if(task.type==='pickup')action={type:'pickup',id:task.id};
    else action={type:'deliver'};
  } else if(taskGoal) action=chooseMove(taskGoal);
  else action=chooseMove(null);
  return {action,memory};
}

module.exports={act};
