 function bfs(sx,sy){const d=new Int16Array(W*H);d.fill(-1);const q=new Int16Array(W*H);let a=0,b=0,s=K(sx,sy);if(!F(sx,sy))return d;d[s]=0;q[b++]=s;while(a<b){let p=q[a++],x=p%W,y=p/W|0;for(let z of D){let X=x+z[1],Y=y+z[2],n=K(X,Y);if(F(X,Y)&&d[n]<0)d[n]=d[p]+1,q[b++]=n}}return d}
 if(!m||m.v!==7){let P=[];function add(p){for(let i=0;i<P.length;i++)if(P[i][0]==p.x&&P[i][1]==p.y)return;P.push([p.x,p.y])}o.chargers.forEach(add);o.jobs.forEach(j=>{add(j.from);add(j.to)});let dm=[];for(let p of P){let d=bfs(p[0],p[1]);for(let q of P)dm.push(d[K(q[0],q[1])])}m={v:7,P,dm,t:null,pt:-99,last:null}}
 const P=m.P,N=P.length,pi=p=>{for(let i=0;i<N;i++)if(P[i][0]==p.x&&P[i][1]==p.y)return i;return-1},pd=(a,b)=>{let d=m.dm[a*N+b];return d<0?999:d};
 const C=bfs(o.courier.x,o.courier.y),cd=p=>{let d=C[K(p.x,p.y)];return d<0?999:d},J={};o.jobs.forEach(j=>J[j.id]=j);
 function weight(mask){let w=0;if(mask===undefined){for(let id of o.courier.cargo)if(J[id])w+=J[id].weight}else for(let i=0;i<o.jobs.length;i++)if(mask>>i&1)w+=o.jobs[i].weight;return w}
