  function go(loc,p){return loc<0?cd(p):pd(loc,pi(p))}function better(a,b){return a.v>b.v||a.v==b.v&&(a.c>b.c||a.c==b.c&&a.e<b.e)}
  function f(loc,time,A,C,first){for(let i=0;i<n;i++)if(o.jobs[i].deadline<time)A&=~(1<<i),C&=~(1<<i);let best={v:0,c:0,e:time,f:first},w=weight(C);
   for(let i=0;i<n;i++)if(A>>i&1){let j=o.jobs[i],d=go(loc,j.from),nt=time+d+1;if(w+j.weight<=3&&d<999&&nt<=j.deadline){let r=f(pi(j.from),nt,A&~(1<<i),C|1<<i,first||{type:'pickup',id:j.id,x:j.from.x,y:j.from.y});if(better(r,best))best=r}}
