   return best}
  return f(-1,o.tick,av,car,null).f}
 if(!valid(m.t)||o.tick-m.pt>=7)m.t=plan(),m.pt=o.tick;
 let t=m.t,g=t?{x:t.x,y:t.y}:null,w=weight(),cost=w>3?2:1,charge=false,need=0;
