 if(g){let dg=cd(g),reserve=4;if(t.type=='deliver')reserve=nc(g)+10;else{let j=J[t.id],c=w+j.weight>3?2:1;reserve=Math.min(nc(g)*c,pd(pi(j.from),pi(j.to))*c+nc(j.to)+8)+8}let req=dg*cost+reserve,q=nearest();if(o.courier.battery<=dg*cost+3||o.courier.battery<Math.min(82,req)){if(q.p&&!(q.d==0&&o.courier.battery>=Math.min(90,Math.max(60,req))))charge=true,g={x:q.p.x,y:q.p.y},need=Math.min(90,Math.max(60,req))}if(q.d==0&&o.courier.battery<75)charge=true,g={x:q.p.x,y:q.p.y},need=Math.min(90,Math.max(78,req))}else if(!g){let q=nearest();if(q.p&&o.courier.battery<75)charge=true,g=q.p,need=90}
 function hstep(e,tx,ty){if(e.x==tx&&e.y==ty)return[e.x,e.y];let q=new Int16Array(W*H),seen=new Uint8Array(W*H),first=new Int16Array(W*H),a=0,b=0,s=K(e.x,e.y);q[b++]=s;seen[s]=1;while(a<b){let p=q[a++],x=p%W,y=p/W|0;for(let z of D){let X=x+z[1],Y=y+z[2],n=K(X,Y);if(!F(X,Y)||seen[n])continue;seen[n]=1;first[n]=p==s?n:first[p];if(X==tx&&Y==ty){let v=first[n];return[v%W,v/W|0]}q[b++]=n}}return[e.x,e.y]}
 function safe(x,y,wait){if(!F(x,y))return null;if(!wait&&(o.courier.battery<cost||o.courier.battery==cost&&!o.chargers.some(c=>c.x==x&&c.y==y)))return null;let risk=0;for(let e of o.enemies){if(x==e.x&&y==e.y)return null;let X=e.x,Y=e.y,mv=e.kind=='hunter'?o.tick%2==0:o.tick%3==0;if(mv){if(e.kind=='hunter'){[X,Y]=hstep(e,x,y);if(X==x&&Y==y)return null}else if(Math.abs(e.x-x)+Math.abs(e.y-y)==1)return null}let d=Math.abs(X-x)+Math.abs(Y-y);risk+=e.kind=='hunter'?(d==1?5:d==2?2:d==3?.5:0):(d==1?4:d==2?1:0)}return risk}
 function move(goal){let gd=goal?bfs(goal.x,goal.y):null,b=null;for(let i=0;i<5;i++){let wait=i==4,x=o.courier.x+(wait?0:D[i][1]),y=o.courier.y+(wait?0:D[i][2]),r=safe(x,y,wait);if(r===null)continue;let d=goal?gd[K(x,y)]:0;if(d<0)d=999;let s=d*8+r+(wait?2.2:0)+(m.last&&x==m.last[0]&&y==m.last[1]?1.2:0);if(!b||s<b.s)b={i,s}}m.last=[o.courier.x,o.courier.y];return !b||b.i==4?{type:'wait'}:{type:'move',dir:D[b.i][0]}}
 let here=g&&o.courier.x==g.x&&o.courier.y==g.y,a;if(charge&&here&&o.courier.battery<need)a=safe(o.courier.x,o.courier.y,true)!==null?{type:'charge'}:move(g);else if(!charge&&t&&here)a=safe(o.courier.x,o.courier.y,true)===null?move(g):t.type=='pickup'?{type:'pickup',id:t.id}:{type:'deliver'};else a=g?move(g):move(null);return{action:a,memory:m}
